LABELS = {"social": "Social", "balanced": "Balanced", "linear": "Linear", "orbit": "Orbit", "galaxy": "Galaxy",
          "skyline": "Skyline", "river": "Flow river", "pulse": "Pulse", "clock": "Day clock", "neural": "Neural net",
          "rain": "Code rain", "ridgelines": "Ridgelines"}
